import {lineNoiseFields,lineNoiseSettings} from '../scene/line-noise.js';
export const curvePresets={linear:[0,0,1,1],easeIn:[.42,0,1,1],easeOut:[0,0,.58,1],easeInOut:[.42,0,.58,1]};
export function validCurve(v){return Array.isArray(v)&&v.length===4&&v.every(Number.isFinite)&&v[0]>=0&&v[0]<=1&&v[2]>=0&&v[2]<=1&&v[1]>=-2&&v[1]<=3&&v[3]>=-2&&v[3]<=3;}
export function cubicProgress(t,c){if(t<=0)return 0;if(t>=1)return 1;const at=(u,a,b)=>3*(1-u)**2*u*a+3*(1-u)*u*u*b+u**3;let lo=0,hi=1;for(let i=0;i<32;i++){const u=(lo+hi)/2;if(at(u,c[0],c[2])<t)lo=u;else hi=u;}return at((lo+hi)/2,c[1],c[3]);}
export function limitValue(prop,value){if(Object.hasOwn(lineNoiseFields,prop))return lineNoiseSettings({[prop]:value})[prop];return ['opacity','shadowOpacity'].includes(prop)?Math.max(0,Math.min(1,value)):['strokeWidth','shadowBlur'].includes(prop)?Math.max(0,Math.min(prop==='shadowBlur'?200:10000,value)):value;}
export function moveGraphKey(track,id,time,value,prop,duration,fps){const i=track.findIndex(k=>k.id===id);if(i<0)return;const min=i?track[i-1].time+1/fps:0,max=i<track.length-1?track[i+1].time-1/fps:duration;if(min>max)return;track[i].time=Math.max(min,Math.min(max,Math.round(time*fps)/fps));if(typeof track[i].value==='number'&&Number.isFinite(value))track[i].value=limitValue(prop,value);}
